+
+  const letters = "QWERTYUIOPASDFGHJKLZXCVBNM".split("");
+
+  const wordToGuess = "guess".toUpperCase();
+  // const wordToGuess = prompt("Enter a word to guess:").toUpperCase();
+
+  useEffect(() => {
+    const allLettersGuessed = wordToGuess
+      .split("")
+      .every((letter) => guessedLetters.includes(letter));
+    if (allLettersGuessed && !isGameWon && !isGameOver) {
+      setIsGameWon(true);
+      alert("Congratulations! You won!");
+    }
+  }, [guessedLetters, wordToGuess, isGameWon, isGameOver]);
+
+  useEffect(() => {
+    if (errorsCount >= 6 && !isGameOver && !isGameWon) {
+      setIsGameOver(true);
+      alert(`Game Over! The word was: ${wordToGuess}`);
+    }
+  }, [errorsCount, isGameOver, isGameWon, wordToGuess]);
+
+  const onLetterClick = (letter) => {
+    if (isGameOver || isGameWon) return;
+    if (guessedLetters.includes(letter)) {
+      alert(`You already guessed ${letter}`);
+      return;
+    }
+    if (!wordToGuess.includes(letter)) {
+      setErrorsCount((prev) => prev + 1);
+      setClickedLetters((prev) => [...prev, letter]);
+    } else {
+      setGuessedLetters((prev) => [...prev, letter]);
+      setClickedLetters((prev) => [...prev, letter]);
+    }
+  };
+
+  const onReset = () => {
+    setErrorsCount(0);
+    setGuessedLetters([]);
+    setClickedLetters([]);
+    setIsGameOver(false);
+    setIsGameWon(false);
+  };
+
+  return (
