+import "./App.css";
+import Hangman0 from "./assets/Hangman-0.png";
+import Hangman1 from "./assets/Hangman-1.png";
+import Hangman2 from "./assets/Hangman-2.png";
+import Hangman3 from "./assets/Hangman-3.png";
+import Hangman4 from "./assets/Hangman-4.png";
+import Hangman5 from "./assets/Hangman-5.png";
+import Hangman6 from "./assets/Hangman-6.png";
+import { useState, useEffect, useCallback } from "react";
+import { Hangman } from "./components/Hangman";
+import { LetterPlaceholder } from "./components/LetterPlaceholder";
+
+const App = () => {
+  const [errorsCount, setErrorsCount] = useState(0);
+  const [guessedLetters, setGuessedLetters] = useState([]);
+  const [clickedLetters, setClickedLetters] = useState([]);
+
+  // Производные состояния
+  const wordToGuess = "GUESS"; // или любое другое слово
+  const isGameWon = wordToGuess
+    .split("")
+    .every((letter) => guessedLetters.includes(letter));
+  const isGameOver = errorsCount >= 6;
+
+  // Рефы для однократного показа алертов
+  const hasShownWinAlert = useRef(false);
+  const hasShownLoseAlert = useRef(false);
+
+  const images = [
+    Hangman0,
+    Hangman1,
+    Hangman2,
+    Hangman3,
+    Hangman4,
+    Hangman5,
+    Hangman6,
+  ];
+
+  const letters = "QWERTYUIOPASDFGHJKLZXCVBNM".split("");
+
+  // Эффект для алерта победы
+  useEffect(() => {
+    if (isGameWon && !hasShownWinAlert.current) {
+      hasShownWinAlert.current = true;
+      alert("Congratulations! You won!");
+    }
+  }, [isGameWon]);
+
+  // Эффект для алерта поражения
+  useEffect(() => {
+    if (isGameOver && !hasShownLoseAlert.current) {
+      hasShownLoseAlert.current = true;
+      alert(`Game Over! The word was: ${wordToGuess}`);
+    }
+  }, [isGameOver, wordToGuess]);
+
+  const onLetterClick = useCallback(
+    (letter) => {
+      if (isGameOver || isGameWon) return;
+      if (guessedLetters.includes(letter)) {
+        alert(`You already guessed ${letter}`);
+        return;
+      }
+      if (!wordToGuess.includes(letter)) {
+        setErrorsCount((prev) => prev + 1);
+        setClickedLetters((prev) => [...prev, letter]);
+      } else {
+        setGuessedLetters((prev) => [...prev, letter]);
+        setClickedLetters((prev) => [...prev, letter]);
+      }
+    },
+    [isGameOver, isGameWon, guessedLetters, wordToGuess],
+  );
+
+  const onReset = () => {
+    setErrorsCount(0);
+    setGuessedLetters([]);
+    setClickedLetters([]);
+    // Сбрасываем рефы алертов, чтобы при новой игре они снова сработали
+    hasShownWinAlert.current = false;
+    hasShownLoseAlert.current = false;
+  };
+
+  // Клавиатурный ввод (с использованием event.code)
+  useEffect(() => {
+    const handleKeyDown = (event) => {
+      if (isGameOver || isGameWon) return;
+      if (
+        event.target.tagName === "INPUT" ||
+        event.target.tagName === "TEXTAREA"
+      )
+        return;
+      if (!event.code.startsWith("Key")) return;
+
+      const letter = event.code.slice(3); // "KeyA" -> "A"
+      if (!event.metaKey && !event.ctrlKey && !event.altKey) {
+        event.preventDefault();
+      }
+
+      if (clickedLetters.includes(letter)) {
+        alert(`You already pressed ${letter}`);
+        return;
+      }
+
+      onLetterClick(letter);
+    };
+
+    document.addEventListener("keydown", handleKeyDown);
+    return () => document.removeEventListener("keydown", handleKeyDown);
+  }, [isGameOver, isGameWon, clickedLetters, onLetterClick]);
+
+  return (
+    <>
+      <h1>Hangman</h1>
+      <p>Errors count: {errorsCount}</p>
+      <Hangman images={images} errorsCount={errorsCount} />
+      <div className="answer-container">
+        {[...wordToGuess].map((letter, index) => (
+          <span key={index} className="letter-placeholder">
+            <LetterPlaceholder
+              letter={letter}
+              isVisible={guessedLetters.includes(letter) ? true : false}
+            />
+          </span>
+        ))}
+      </div>
+      <div className="letters-container">
+        {letters.map((letter) => (
+          <button
+            className={`letter-button ${clickedLetters.includes(letter) && guessedLetters.includes(letter) ? "letter-guessed" : ""}`}
+            key={letter}
+            onClick={() => onLetterClick(letter)}
+            disabled={
+              !guessedLetters.includes(letter) &&
+              clickedLetters.includes(letter)
+            }
+          >
+            {letter}
+          </button>
+        ))}
+        <button className="letter-button reset-button" onClick={onReset}>
+          Reset
+        </button>
+      </div>
+    </>
+  );
+};
+
+export default App;

