+import "./App.css";
+import Hangman0 from "./assets/Hangman-0.png";
+import Hangman1 from "./assets/Hangman-1.png";
+import Hangman2 from "./assets/Hangman-2.png";
+import Hangman3 from "./assets/Hangman-3.png";
+import Hangman4 from "./assets/Hangman-4.png";
+import Hangman5 from "./assets/Hangman-5.png";
+import Hangman6 from "./assets/Hangman-6.png";
+import { useState, useEffect, useCallback, useRef, use } from "react";
+import { Hangman } from "./components/Hangman";
+import { LetterPlaceholder } from "./components/LetterPlaceholder";
+import { words } from "./data/words";
+
+const App = () => {
+  const [errorsCount, setErrorsCount] = useState(0);
+  const [guessedLetters, setGuessedLetters] = useState([]);
+  const [clickedLetters, setClickedLetters] = useState([]);
+  const [wordToGuess, setWordToGuess] = useState("");
+  const [loading, setLoading] = useState(true);
+  const [error, setError] = useState(null);
+
+  const getRandomWord = () => {
+    return words[Math.floor(Math.random() * words.length)].toUpperCase();
+  };
+
+  // Функция для получения случайного слова
+  const fetchNewWord = useCallback(async () => {
+    setLoading(true);
+    setError(null);
+    try {
+      const response = await fetch(
+        "https://random-words-api.kushcreates.com/api?language=en&category=countries&type=uppercase&words=1",
+      );
+      if (!response.ok) throw new Error("Failed to fetch word");
+      const data = await response.json();
+      setWordToGuess(data[0].word.toUpperCase());
+    } catch (err) {
+      setError(err.message);
+      // Запасной вариант на случай ошибки
+      setWordToGuess("ERROR");
+    } finally {
+      setLoading(false);
+    }
+  }, []);
+
+  useEffect(() => {
+    fetchNewWord();
+  }, [fetchNewWord]);
+
+  const isGameWon = wordToGuess
+    .split("")
+    .every((letter) => guessedLetters.includes(letter));
+  const isGameOver = errorsCount >= 6;
+
+  useEffect(() => {
+    if (wordToGuess.includes("-")) {
+      setGuessedLetters((prev) => [...prev, "-"]);
+    }
+
+    if (wordToGuess.includes(" ")) {
+      setGuessedLetters((prev) => [...prev, " "]);
+    }
+  }, [wordToGuess]);
+
+  const hasShownWinAlert = useRef(false);
+  const hasShownLoseAlert = useRef(false);
+
+  const images = [
+    Hangman0,
+    Hangman1,
+    Hangman2,
+    Hangman3,
+    Hangman4,
+    Hangman5,
+    Hangman6,
+  ];
+
+  const topRow = "QWERTYUIOP".split("");
+  const middleRow = "ASDFGHJKL".split("");
+  const bottomRow = "ZXCVBNM".split("");
+
+  useEffect(() => {
+    if (
+      isGameWon &&
+      !hasShownWinAlert.current &&
+      !hasShownLoseAlert.current &&
+      !loading
+    ) {
+      hasShownWinAlert.current = true;
+      setTimeout(() => {
+        alert("Congratulations! You won!");
+      }, 200);
+    }
+  }, [isGameWon, loading]);
+
+  useEffect(() => {
+    if (
+      isGameOver &&
+      !hasShownLoseAlert.current &&
+      !hasShownWinAlert.current &&
+      !loading
+    ) {
+      hasShownLoseAlert.current = true;
+      // setGuessedLetters(wordToGuess.split(""));
+      setTimeout(() => {
+        alert(`Game Over! The word was: ${wordToGuess}`);
+      }, 200);
+    }
+  }, [isGameOver, wordToGuess, loading]);
+
+  const onLetterClick = useCallback(
+    (letter) => {
+      if (isGameOver || isGameWon || loading) return;
+      if (guessedLetters.includes(letter)) {
+        alert(`You already guessed ${letter}`);
+        return;
+      }
+      if (!wordToGuess.includes(letter)) {
+        setErrorsCount((prev) => prev + 1);
+        setClickedLetters((prev) => [...prev, letter]);
+      } else {
+        setGuessedLetters((prev) => [...prev, letter]);
+        setClickedLetters((prev) => [...prev, letter]);
+      }
+    },
+    [isGameOver, isGameWon, guessedLetters, wordToGuess, loading],
+  );
+
+  const onReset = () => {
+    setErrorsCount(0);
+    setGuessedLetters([]);
+    setClickedLetters([]);
+    fetchNewWord();
+    hasShownWinAlert.current = false;
+    hasShownLoseAlert.current = false;
+  };
+
+  // Клавиатурный ввод (без изменений)
+  useEffect(() => {
+    const handleKeyDown = (event) => {
+      if (isGameOver || isGameWon || loading) return;
+      if (
+        event.target.tagName === "INPUT" ||
+        event.target.tagName === "TEXTAREA"
+      )
+        return;
+      if (!event.code.startsWith("Key")) return;
+
+      const letter = event.code.slice(3);
+      if (!event.metaKey && !event.ctrlKey && !event.altKey) {
+        event.preventDefault();
+      }
+
+      if (clickedLetters.includes(letter)) {
+        alert(`You already pressed ${letter}`);
+        return;
+      }
+
+      onLetterClick(letter);
+    };
+
+    document.addEventListener("keydown", handleKeyDown);
+    return () => document.removeEventListener("keydown", handleKeyDown);
+  }, [isGameOver, isGameWon, clickedLetters, onLetterClick, loading]);
+
+  if (loading) {
+    return (
+      <>
+        <h1>Hangman</h1>
+        <p>Loading word...</p>
+        <Hangman images={images} errorsCount={errorsCount} />
+        <button onClick={onReset}>Reset</button>
+      </>
+    );
+  }
+
+  if (error) {
+    return (
+      <>
+        <h1>Hangman</h1>
+        <p>Error: {error}</p>
+        <button onClick={onReset}>Try Again</button>
+      </>
+    );
+  }
+
+  return (
+    <>
+      <h1>Hangman</h1>
+      <p>Errors count: {errorsCount}</p>
+      <Hangman images={images} errorsCount={errorsCount} />
+      <div className="answer-container">
+        {[...wordToGuess].map((letter, index) => (
+          <span key={index} className="letter-placeholder">
+            <LetterPlaceholder
+              letter={letter}
+              isVisible={guessedLetters.includes(letter)}
+              isGameOver={isGameOver}
+              isGameWon={isGameWon}
+            />
+          </span>
+        ))}
+      </div>
+      <div className="keyboard">
+        <div className="keyboard-row">
+          {topRow.map((letter) => (
+            <button
+              key={letter}
+              className={`letter-button ${
+                clickedLetters.includes(letter) &&
+                guessedLetters.includes(letter)
+                  ? "letter-guessed"
+                  : ""
+              }`}
+              onClick={() => onLetterClick(letter)}
+              disabled={
+                !guessedLetters.includes(letter) &&
+                clickedLetters.includes(letter)
+              }
+            >
+              {letter}
+            </button>
+          ))}
+        </div>
+        <div className="keyboard-row">
+          {middleRow.map((letter) => (
+            <button
+              key={letter}
+              className={`letter-button ${
+                clickedLetters.includes(letter) &&
+                guessedLetters.includes(letter)
+                  ? "letter-guessed"
+                  : ""
+              }`}
+              onClick={() => onLetterClick(letter)}
+              disabled={
+                !guessedLetters.includes(letter) &&
+                clickedLetters.includes(letter)
+              }
+            >
+              {letter}
+            </button>
+          ))}
+        </div>
+        <div className="keyboard-row">
+          {bottomRow.map((letter) => (
+            <button
+              key={letter}
+              className={`letter-button ${
+                clickedLetters.includes(letter) &&
+                guessedLetters.includes(letter)
+                  ? "letter-guessed"
+                  : ""
+              }`}
+              onClick={() => onLetterClick(letter)}
+              disabled={
+                !guessedLetters.includes(letter) &&
+                clickedLetters.includes(letter)
+              }
+            >
+              {letter}
+            </button>
+          ))}
+        </div>
+        <button className="letter-button reset-button" onClick={onReset}>
+          New Word
+        </button>
+      </div>
+    </>
+  );
+};
+
+export default App;

